import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"艮下兑上 咸：","description":"京氏易传 - 艮下兑上 咸：","frontmatter":{"title":"艮下兑上 咸：","description":"京氏易传 - 艮下兑上 咸："},"headers":[],"relativePath":"zh/classics/jingshi/061.md","filePath":"zh/classics/jingshi/061.md"}'),r={name:"zh/classics/jingshi/061.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"艮下兑上-咸",tabindex:"-1"},[i("艮下兑上 咸： "),e("a",{class:"header-anchor",href:"#艮下兑上-咸","aria-label":"Permalink to “艮下兑上 咸：”"},"​")],-1),e("p",null,"山下有泽，（虎易注：下字当为上字之误。《咸》象曰：山上有泽，咸；君子以虚受人。）虚已畜物，阳中积阴，感于物也。阳下于阴，男女之道，内外相应，感类于象也。六二待聘，九五见召，二气交感，夫妇之道，体斯合也。《易》曰：“咸，感也，利取吉女。”（虎易注：此处错句。《咸》彖曰：咸，感也。柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也。）【艮少男，兑少女，男下于女，取妇之象。】与艮为飞伏。【丙申金，丁丑土。】九三三宫居世，上六宗庙为应。",-1),e("p",null,"建始戊午之癸亥，【芒种，小雪。】积算起癸亥至壬戌，周而复始。火土入艮兑。【分火土象入艮兑也。】",-1),e("p",null,"五星从位起荧惑，【火星南方入金宫。】柳宿从位降丙申，【二十八宿，分柳宿入咸九三丙申金爻上。】分气候三十六。【积算起数，分三十六位起吉凶。】",-1),e("p",null,"土上见金，母子气和，阴阳相应，刚柔定位。吉凶随爻，受气出则吉，刑则凶。阴阳等降入外险，止于内象，为山水蹇卦。（虎易注：当为水山蹇卦之误。）【九四爻之入阴中刚。】",-1)])])}const f=s(r,[["render",l]]);export{_ as __pageData,f as default};
